import {DatabaseSync} from 'node:sqlite';
import {DOMAIN_SCHEMA} from '../../src/domain/schema.js';
import {ANALYSIS_SCHEMA} from '../../src/analysis/schema.js';
import {buildMatchAnalysisPage} from '../../src/analysis/projector.js';
const AT='2026-10-12T12:00:00Z';
export function analysisFixture({format=7,players=format,minutes=25,proof=true,root=true}={}){
 const sqlite=new DatabaseSync(':memory:');sqlite.exec('PRAGMA foreign_keys=ON;');for(const sql of [...DOMAIN_SCHEMA,...ANALYSIS_SCHEMA])sqlite.exec(sql);
 const insert=(table,row)=>sqlite.prepare(`INSERT INTO ${table}(${Object.keys(row).join(',')}) VALUES(${Object.keys(row).map(()=>'?').join(',')})`).run(...Object.values(row));
 let queries=0;const db={prepare(sql){const statement={sql,params:[],bind(...params){return {...statement,params};},async first(){queries++;return sqlite.prepare(sql).get(...this.params)||null;},async all(){queries++;const results=sqlite.prepare(sql).all(...this.params).map(v=>({...v}));return {results,meta:{changes:sqlite.prepare('SELECT changes() AS count').get().count}};}};return statement;},async batch(statements){sqlite.exec('BEGIN');try{const results=await Promise.all(statements.map(s=>s.all()));sqlite.exec('COMMIT');return results;}catch(error){sqlite.exec('ROLLBACK');throw error;}}};
 insert('domain_installation',{id:1,schema_version:1,created_at:AT});insert('provider_accounts',{id:'account',provider:'trace',native_id:'1',name:'Account'});insert('app_teams',{id:'team',name:'Us',timezone:'UTC',season_year:2026,created_at:AT});insert('team_read_state',{app_team_id:'team'});insert('team_seasons',{id:'season',app_team_id:'team',year:2026,start_day:'2026-06-01',end_day:'2027-06-01',start_at:'2026-06-01T00:00:00Z',end_at:'2027-06-01T00:00:00Z',include_june:0});insert('team_projection_runs',{id:'team-run',app_team_id:'team',team_season_id:'season',input_revision:1,state:'published',created_at:AT});insert('team_projection_state',{team_season_id:'season',app_team_id:'team',published_run_id:'team-run',pending:0});
 insert('source_teams',{id:'source-team',provider:'trace',scope:'account',account_id:'account',native_id:'10',name:'Us',name_authority:3,archived:0,evidence:'{}',content_hash:'team',observed_at:AT});insert('team_source_attachments',{id:'attachment',app_team_id:'team',team_season_id:'season',source_team_id:'source-team',account_id:'account'});
 if(root){insert('team_source_connections',{id:'root',app_team_id:'team',source_team_id:'source-team',account_id:'account',scope_mode:'observed_history',created_at:AT});insert('team_connection_seasons',{connection_id:'root',team_season_id:'season',attachment_id:'attachment',basis:'events'});}
 insert('events',{id:'event',created_at:AT});insert('source_events',{id:'source-event',provider:'trace',scope:'account',account_id:'account',native_id:'20',local_day:'2026-09-01',time_precision:'day',type:'game',status:'final',conditional:0,home_source_team_id:'source-team',home_label:'Us',away_label:'Them',home_score:0,away_score:0,title:'Game',venue:'Field',evidence:'{}',content_hash:'event',observed_at:AT});insert('source_event_teams',{source_team_id:'source-team',source_event_id:'source-event',side:'home'});insert('event_source_links',{source_event_id:'source-event',event_id:'event',reason:'native',evidence:'{}'});insert('team_event_season_resolutions',{app_team_id:'team',event_id:'event',team_season_id:'season',state:'resolved',effective_day:'2026-09-01',basis:'date',evidence:'{}'});insert('team_event_rows',{run_id:'team-run',app_team_id:'team',team_season_id:'season',event_id:'event',local_day:'2026-09-01',type:'game',status:'FINAL',conditional:0,own_side:'home',home_name:'Us',away_name:'Them',goals_for:0,goals_against:0,title:'Game',venue:'Field',source_ids:'["source-event"]',schedule_source_id:'source-event',result_source_id:'source-event'});
 const common={account_id:'account',source_team_id:'source-team',source_event_id:'source-event',content_hash:'test',observed_at:AT};
 insert('source_trace_components',{...common,id:'header',native_key:'header',kind:'header',availability:'ready',evidence:JSON.stringify({moment_count:0})});insert('source_component_coverage',{id:'game-coverage',provider:'trace',scope:'trace:20:trace:10',account_id:'account',kind:'game',complete:1,record_count:0,scan_id:'scan',observed_at:AT});
 for(const half of [1,2]){
  insert('source_trace_components',{...common,id:'clip-'+half,native_key:'clip:'+half,kind:'clip',half,duration_seconds:minutes*60,evidence:JSON.stringify({game_clip_id:half,start:half*1_000_000,duration:minutes*60,half})});
  insert('source_trace_components',{...common,id:'radar-'+half,native_key:'radar:'+half,kind:'radar',half,start_seconds:0,end_seconds:minutes*60,population:format*2,evidence:JSON.stringify({...(proof?{analysis:{play_window:{start:0,end:minutes*60,baseline_tracks:format*2,complete:true},both_sides_verified:true,track_roles:Array.from({length:players},(_,i)=>({gid:'g'+i,side:'home',verified:true,role:i===0?'goalkeeper':'field'}))}}:{})})});
 }
 for(let i=0;i<players;i++){
  const player='player-'+String(i).padStart(3,'0'),source='native-'+i;
  insert('players',{id:player,created_at:AT});insert('source_players',{id:source,provider:'trace',scope:'account',account_id:'account',native_id:String(i),name:player,jersey:String(i),evidence:'{}',content_hash:'player',observed_at:AT});insert('player_source_links',{source_player_id:source,player_id:player,reason:'native',evidence:'{}'});insert('team_player_rows',{run_id:'team-run',app_team_id:'team',team_season_id:'season',player_id:player,name:player,jersey:String(i),source_ids:JSON.stringify([source])});insert('source_game_members',{...common,id:'member-'+i,native_key:'member:'+i,source_player_id:source,gid:'g'+i,side:'home',name:player,jersey:String(i),dummy:0,position:i===0?'GK':i<3?'DEF':i<6?'MID':'FWD',evidence:'{}'});
  for(const half of [1,2]){insert('source_tracking_segments',{...common,id:`segments-${i}-${half}`,source_player_id:source,gid:'g'+i,half,chunk:0,page_offset:0,segments:JSON.stringify([[0,minutes*60]])});insert('source_component_coverage',{id:`tracking-${i}-${half}`,provider:'trace',scope:`trace:20:trace:10:g${i}:${half}`,account_id:'account',kind:'tracking',complete:1,record_count:1,scan_id:'scan',observed_at:AT});}
 }
 const commit=page=>{sqlite.exec('BEGIN');try{for(const s of page.statements)sqlite.prepare(s.sql.replaceAll('$FENCE','1')).run(...s.params);sqlite.exec('COMMIT');}catch(e){sqlite.exec('ROLLBACK');throw e;}};
 const page=()=>buildMatchAnalysisPage(db,{teamId:'team',seasonId:'season',eventId:'event'}),all=sql=>sqlite.prepare(sql).all().map(v=>({...v})),override=(player,fields)=>insert('analysis_overrides',{app_team_id:'team',team_season_id:'season',kind:'player_match',event_id:'event',player_id:player,fields:JSON.stringify(fields),revision:1,updated_at:AT});return {sqlite,db,insert,commit,page,all,override,queries:()=>queries,close:()=>sqlite.close()};
}
